/usr/bin/python3 -c 'import json,os,sys,re,subprocess
if not os.environ.get("PAPERCLIP_AGENT_ID"): sys.exit(0)
try:
    d=json.load(sys.stdin)
except Exception:
    sys.exit(0)
if d.get("tool_name")!="Bash": sys.exit(0)
c=(d.get("tool_input") or {}).get("command") or ""
cwd=d.get("cwd") or "."
P=("main","master")
def block(m):
    sys.stderr.write("QTS guardrail: "+m+". Company file section 4: open a PR; only Warden merges. Ask Zeus if you believe this is wrong.\n")
    sys.exit(2)
def branch():
    try:
        return subprocess.run(["git","-C",cwd,"rev-parse","--abbrev-ref","HEAD"],capture_output=True,text=True,timeout=5).stdout.strip()
    except Exception:
        return ""
def strip_heredocs(src):
    out=[];skip=None
    for line in src.split("\n"):
        if skip is not None:
            if line.strip()==skip: skip=None
            continue
        m=re.search(r"<<-?\s*[\x27\"]?([A-Za-z_][A-Za-z0-9_]*)[\x27\"]?",line)
        if m:
            skip=m.group(1)
            out.append(line[:m.start()])
            continue
        out.append(line)
    return "\n".join(out)
for seg in re.split(r"&&|\|\||;|\n",strip_heredocs(c)):
    t=seg.split()
    if len(t)<2: continue
    if t[0]=="cd":
        d2=t[1].strip(chr(34)+chr(39))
        cwd=d2 if os.path.isabs(d2) else os.path.join(cwd,d2)
        continue
    if t[0]=="git" and "push" in t[1:4]:
        i=t.index("push")
        if any(a in ("--force","-f","--force-with-lease","--force-if-includes") or a.startswith("--force") for a in t[i:]):
            block("force-push is blocked")
        wide=[a for a in t[i:] if a in ("--all","--mirror")]
        if wide:
            block("git push "+wide[0]+" is blocked")
        refs=[a for a in t[i+1:] if not a.startswith("-")]
        if any(a.startswith("+") for a in refs):
            block("force-push by plus-refspec is blocked")
        targets=[a.split(":")[-1].replace("refs/heads/","") for a in refs[1:]] if len(refs)>1 else []
        if not targets:
            b=branch()
            if b in P: block("git push from a checkout of "+b+" is blocked")
        for a in targets:
            if a in P: block("git push to "+a+" is blocked")
    if t[0]=="gh" and "pr" in t and "merge" in t and "--admin" in t:
        block("gh pr merge --admin is blocked")
sys.exit(0)'
